import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const AuditLogContext = createContext()

export const AuditLogContextProvider = (props) => {
  return (
    <AuditLogContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </AuditLogContext.Provider>
  )
}

export const useAuditLogContextValue = () => useContext(AuditLogContext)
