/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from "react"
import {
  Form,
  Button,
  Icon,
  Row,
  Col,
  Select,
  Empty,
  Spin,
  Tag,
  notification
} from "antd"
import QueryString from "query-string"
import moment from "moment-timezone"
import ReactJson from "react-json-view"

import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from "@pasarpolis/common-react-hooks"

import { FilterSelectOption } from "../../../../../components/tables/helperCells"
import LayoutContent from "../../../../../components/utility/layoutContent"
import LayoutContentWrapper from "../../../../../components/utility/layoutWrapper"
import TableWrapper from "../../pagination.style"
import AuditLogListWrapper from "./style"
import QuerySearchBuilder from "../../../../../helpers/querySearchBuilder"
import {
  useGetAuditLog,
  useGetCategory,
  useGetUserList,
  useResetState
} from "../../state/hooks/useAuditLogContext"

const { Option } = Select

export const AuditLogs = ({ location, history }) => {
  const [filterCategory, setFilterCategory] = useState(false)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  const [page, setPage] = useState(1)
  const [isUserSelected, setUserSelected] = useState(false)
  const [{ getAuditDataData = {} }, getAuditLogRequest] = useGetAuditLog()
  const [{ getCategoriesData = [] }, getCategoryRequest] = useGetCategory()
  const [{ getUserListData = [] }, getUserListRequest] = useGetUserList()
  const [resetState] = useResetState()
  const [{ GET_AUDIT_DATA_LOADER }] = useLoaderContextValue()
  const [
    {
      GET_AUDIT_DATA_ERROR = "",
      GET_CATEGORIES_ERROR = "",
      GET_USER_LIST_ERROR = "",
      getUserListStatus = "",
      getCategoriesStatus = "",
      getAuditDataStatus = ""
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    const { category, user_id: userId, reference_id: referenceId } = querySearch
    if (!referenceId) {
      history.replace("/audit-log")
    }
    fetch(querySearch)
    setSearchTextQuery({
      category,
      userId
    })
    setAppliedFilter({ category })
    getCategoryRequest()
    getUserListRequest()
    return () => resetState(["getAuditDataData"])
  }, [])

  //Error handling notify error status
  useEffect(() => {
    if (GET_AUDIT_DATA_ERROR) {
      getAuditDataStatus && notification.error({ message: getAuditDataStatus })
      dispatchError(
        resetError({
          GET_AUDIT_DATA_ERROR: false,
          getAuditDataStatus: ""
        })
      )
    } else if (GET_CATEGORIES_ERROR) {
      getCategoriesStatus &&
        notification.error({ message: getCategoriesStatus })
      dispatchError(
        resetError({
          GET_CATEGORIES_ERROR: false,
          getCategoriesStatus: ""
        })
      )
    } else if (GET_USER_LIST_ERROR) {
      getUserListStatus && notification.error({ message: getUserListStatus })
      dispatchError(
        resetError({
          GET_USER_LIST_ERROR: false,
          getUserListStatus: ""
        })
      )
    }
  }, [GET_AUDIT_DATA_ERROR, GET_CATEGORIES_ERROR, GET_USER_LIST_ERROR])

  const renderTitle = (titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }

  const onInputChange = (value, identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: value
    })

    if (identifier === "userId" && !value) {
      resetState(["getAuditDataData"])
      setUserSelected(false)
      clearQuerySearchBuilder("user_id")
    }
  }

  const onSearch = (e, key) => {
    e.preventDefault()
    const oldSearch = QueryString.parse(location?.search)
    const { reference_id: referenceId } = oldSearch
    const searchText = {}
    searchText["page"] = page
    searchText["reference_id"] = referenceId
    searchText["category"] = searchTextQuery.category
    searchText["user_id"] = searchTextQuery.userId
    const search = QuerySearchBuilder(searchText)
    history.push({ pathname: location?.pathname, search })
    fetch(searchText)
    setFilterCategory(false)
    setAppliedFilter(searchTextQuery)
  }

  const renderIcon = (active) => {
    let iconClass = "filter-icon"
    if (active) {
      iconClass += " active"
    }
    return <Icon className={iconClass} type="filter" theme="outlined" />
  }

  const columns = [
    {
      key: "timeStamp",
      title: renderTitle("title-without-margin", "TimeStamp"),
      dataIndex: "created_at",
      render: (date) => moment(date).tz("Asia/Jakarta").format("lll")
    },
    {
      key: "ip_address",
      title: renderTitle("title-without-margin", "IP Address"),
      dataIndex: "ip_address"
    },
    {
      key: "email",
      title: renderTitle("title-with-margin", "User Email"),
      dataIndex: "user_email"
    },
    {
      key: "category",
      title: renderTitle("title-with-margin", "Category"),
      dataIndex: "category",
      filterDropdown: (
        <FilterSelectOption
          searchText={
            searchTextQuery.category ? searchTextQuery.category : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, "category")}
          onSearch={(e) => onSearch(e, "category")}
          optionData={getCategoriesData}
          renderOption={(data) => {
            return data.map((val) => (
              <option key={Object.values(val)[0]} value={Object.values(val)[0]}>
                {Object.keys(val)[0]}
              </option>
            ))
          }}
        />
      ),
      filterIcon: renderIcon(!!searchTextQuery.category),
      filterDropdownVisible: filterCategory,
      onFilterDropdownVisibleChange: (visible) => setFilterCategory(visible)
    },
    {
      key: "event",
      title: renderTitle("title-with-margin", "Event"),
      dataIndex: "event"
    },
    {
      key: "data",
      title: renderTitle("title-with-margin", "Data"),
      dataIndex: "data",
      render: (data) => (
        <ReactJson
          name="detail"
          src={data}
          displayDataTypes={false}
          displayObjectSize={false}
          enableClipboard={false}
        />
      )
    }
  ]

  const clearQuerySearchBuilder = (identifier) => {
    const oldSearch = QueryString.parse(location?.search)
    delete oldSearch[identifier]
    const search = QuerySearchBuilder(oldSearch)
    history.push({ pathname: location?.pathname, search })
    return oldSearch
  }

  const clearFilter = (identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: undefined
    })
    setAppliedFilter({
      ...appliedFilter,
      [identifier]: undefined
    })

    const oldSearch = clearQuerySearchBuilder(identifier)
    fetch(oldSearch)
  }

  const fetch = (params = {}) => {
    const { page, user_id: userId, reference_id: referenceId } = params
    const pageNumber = Number(page) || 1
    delete params.page

    setPage(pageNumber)
    if (!userId || !referenceId) {
      return
    }
    setUserSelected(true)
    getAuditLogRequest({
      query: {
        ...params,
        page: pageNumber
      }
    })
  }

  const handlePageChange = (val) => {
    const { current } = val
    const querySearch = QueryString.parse(location?.search)
    const searchText = { ...querySearch }
    searchText["page"] = current
    const search = QuerySearchBuilder(searchText)
    history.push({ pathname: location?.pathname, search })
    fetch(searchText)
  }

  const getCategoryValue = () => {
    const category =
      (Array.isArray(getCategoriesData) &&
        getCategoriesData?.filter(
          (category) => Object.values(category)[0] === appliedFilter?.category
        )) ||
      []
    return category.length ? Object.keys(category[0])[0] : ""
  }

  return (
    <LayoutContentWrapper className="referral-table">
      <LayoutContent>
        <AuditLogListWrapper>
          <h2>
            <b>Audit Log</b>
          </h2>
          <Row align="middle" type="flex" className="margin-top">
            <Col xs={{ span: 2 }} lg={{ span: 2 }}>
              <b>User Email</b>
            </Col>
            <Col xs={{ span: 16 }} lg={{ span: 8 }}>
              <Select
                className="auditlog-select"
                value={
                  searchTextQuery.userId ? +searchTextQuery.userId : undefined
                }
                showSearch
                allowClear
                filterOption={(input, option) =>
                  option.props.children
                    .toLowerCase()
                    .indexOf(input.toLowerCase()) >= 0
                }
                placeholder="User Email"
                onChange={(e) => onInputChange(e, "userId")}
              >
                {Array.isArray(getUserListData) &&
                  getUserListData?.map((user) => (
                    <Option key={user.id} value={user.id}>
                      {user.deleted_at ? `${user.email} (deleted)` : user.email}
                    </Option>
                  ))}
              </Select>
            </Col>
            <Col xs={{ offset: 1, span: 8 }} lg={{ offset: 1, span: 4 }}>
              <Button
                type="primary"
                onClick={(e) => onSearch(e, "userId")}
                disabled={!searchTextQuery.userId}
              >
                Search
              </Button>
            </Col>
          </Row>
          {appliedFilter?.category && (
            <Tag className="filter-tag" color="volcano">
              {"category"} - {getCategoryValue()}
              <span
                className="remove-filter"
                onClick={(e) => clearFilter("category")}
              >
                X
              </span>
            </Tag>
          )}
          <Spin spinning={!!GET_AUDIT_DATA_LOADER}>
            {isUserSelected && getAuditDataData?.data?.length ? (
              <TableWrapper
                columns={columns}
                bordered
                rowKey={(record) => record.reference_id}
                dataSource={getAuditDataData.data}
                pagination={{
                  pageSize: 10,
                  total: Number(getAuditDataData?.meta_data?.total),
                  current: getAuditDataData?.meta_data?.page
                }}
                onChange={handlePageChange}
                className="isoSearchableTable"
              />
            ) : (
              <Row justify="center" type="flex" className="margin-top">
                <Empty
                  description={
                    isUserSelected
                      ? "No data found for selected user"
                      : "Select user to proceed"
                  }
                />
              </Row>
            )}
          </Spin>
        </AuditLogListWrapper>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default Form.create({})(AuditLogs)
