import { AUDIT_LOG } from './actions'

export const INITIAL_STATE = {
  getAuditDataData: {
    data: [],
    meta_data: {
      limit: 10,
      page: 1,
      total: 0
    }
  },
  getCategoriesData: [],
  getUserListData: [],
  addAuditReasonData: {}
}

const reducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case AUDIT_LOG.ADD_AUDIT_REASON:
    case AUDIT_LOG.GET_AUDIT_DATA:
    case AUDIT_LOG.GET_CATEGORIES:
    case AUDIT_LOG.GET_USER_LIST:
      return { ...state, ...payload }
    case AUDIT_LOG.RESET_REDUX_STATE_AUDIT:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducer
