import urls from '../../../../config/urls'
const configUrl = urls.url;

export const AUDIT_LOG = {
  ADD_AUDIT_REASON: 'ADD_AUDIT_REASON',
  ADD_AUDIT_REASON_REQUEST: 'ADD_AUDIT_REASON_REQUEST',

  GET_AUDIT_DATA: 'GET_AUDIT_DATA',
  GET_AUDIT_DATA_REQUEST: 'GET_AUDIT_DATA_REQUEST',

  GET_CATEGORIES: 'GET_CATEGORIES',
  GET_CATEGORIES_REQUEST: 'GET_CATEGORIES_REQUEST',

  GET_USER_LIST: 'GET_USER_LIST',
  GET_USER_LIST_REQUEST: 'GET_USER_LIST_REQUEST',
  
  RESET_REDUX_STATE_AUDIT: 'RESET_REDUX_STATE_AUDIT',

  addAuditReason: payload => ({
    type: AUDIT_LOG.ADD_AUDIT_REASON_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.addAuditLogReasonApi
    }
  }),
  getAuditData: payload => ({
    type: AUDIT_LOG.GET_AUDIT_DATA_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getAuditLogApi
    }
  }),
  getCategories: payload => ({
    type: AUDIT_LOG.GET_CATEGORIES_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getCategoriesApi
    }
  }),
  getUserList: payload => ({
    type: AUDIT_LOG.GET_USER_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getUserListApi
    }
  }),
  resetReduxStateAudit: keys => ({
    type: AUDIT_LOG.RESET_REDUX_STATE_AUDIT,
    payload: keys
  })
}
